@push('scripts')<script>(function(){var media=@json($mediaOptions),list=document.getElementById('ot-media-list'),add=document.getElementById('ot-add-media'),index=0;function row(){var i=index++,el=document.createElement('div');el.className='ot-media-row';el.innerHTML='<div><select class="form-control media-name" name="media['+i+'][name]" required><option value="">选择媒体</option>'+media.map(function(x){return '<option>'+x+'</option>'}).join('')+'</select><input class="form-control other-name" name="media['+i+'][custom_name]" placeholder="填写其他媒体名称" style="margin-top:6px"></div><input class="form-control" type="number" min="0" step="0.01" name="media['+i+'][spend]" placeholder="昨日广告费" required><input class="form-control" type="number" min="0" step="1" name="media['+i+'][orders]" placeholder="昨日单量" required><input class="form-control" type="number" min="0" step="0.01" name="media['+i+'][revenue]" placeholder="昨日营业额" required><button type="button" class="btn btn-default remove-media"><i class="fa fa-trash-o"></i></button>';list.appendChild(el)}add.onclick=row;list.addEventListener('change',function(e){if(e.target.classList.contains('media-name')){var other=e.target.parentNode.querySelector('.other-name');other.style.display=e.target.value==='其他'?'block':'none';other.required=e.target.value==='其他'}});list.addEventListener('click',function(e){var b=e.target.closest('.remove-media');if(b&&list.children.length>1)b.closest('.ot-media-row').remove()});row()})();</script>@endpush
